     5→// ---------- Navbar scroll effect ----------
     6→const navbar = document.getElementById('navbar');
     7→function handleNavbarScroll() {
     8→  if (window.scrollY > 20) {
     9→    navbar.classList.add('scrolled');
    10→  } else {
    11→    navbar.classList.remove('scrolled');
    12→  }
    13→}
    14→window.addEventListener('scroll', handleNavbarScroll, { passive: true });
    15→
    16→// ---------- Mobile nav toggle ----------
    17→const navToggle = document.getElementById('navToggle');
    18→const navLinks  = document.getElementById('navLinks');
    19→
    20→navToggle.addEventListener('click', function () {
    21→  const isOpen = navLinks.classList.toggle('open');
    22→  navToggle.setAttribute('aria-expanded', String(isOpen));
    23→});
    24→
    25→// Close mobile nav when a link is clicked
    26→navLinks.querySelectorAll('a').forEach(function (link) {
    27→  link.addEventListener('click', function () {
    28→    navLinks.classList.remove('open');
    29→    navToggle.setAttribute('aria-expanded', 'false');
    30→  });
    31→});
    32→
    33→// ---------- Active nav link on scroll ----------
    34→const sections = document.querySelectorAll('section[id]');
    35→const navItems = document.querySelectorAll('.nav-links a');
    36→
    37→function updateActiveNavLink() {
    38→  const scrollPos = window.scrollY + 100;
    39→  sections.forEach(function (section) {
    40→    if (
    41→      scrollPos >= section.offsetTop &&
    42→      scrollPos < section.offsetTop + section.offsetHeight
    43→    ) {
    44→      navItems.forEach(function (a) {
    45→        a.classList.remove('active');
    46→        if (a.getAttribute('href') === '#' + section.id) {
    47→          a.classList.add('active');
    48→        }
    49→      });
    50→    }
    51→  });
    52→}
    53→window.addEventListener('scroll', updateActiveNavLink, { passive: true });
    54→
    55→// ---------- Intersection Observer – fade-in cards ----------
    56→const fadeEls = document.querySelectorAll(
    57→  '.highlight-card, .interest-card, .publication-card, .contact-card'
    58→);
    59→
    60→const observer = new IntersectionObserver(
    61→  function (entries) {
    62→    entries.forEach(function (entry) {
    63→      if (entry.isIntersecting) {
    64→        entry.target.style.opacity = '1';
    65→        entry.target.style.transform = 'translateY(0)';
    66→        observer.unobserve(entry.target);
    67→      }
    68→    });
    69→  },
    70→  { threshold: 0.1 }
    71→);
    72→
    73→fadeEls.forEach(function (el) {
    74→  el.style.opacity  = '0';
    75→  el.style.transform = 'translateY(20px)';
    76→  el.style.transition = 'opacity 0.5s ease, transform 0.5s ease';
    77→  observer.observe(el);
    78→});
    79→
    80→// ---------- Footer year ----------
    81→const yearEl = document.getElementById('year');
    82→if (yearEl) {
    83→  yearEl.textContent = new Date().getFullYear();
    84→}
