   130→/* ---------- Navbar ---------- */
   131→.navbar {
   132→  position: fixed;
   133→  top: 0;
   134→  width: 100%;
   135→  height: var(--nav-height);
   136→  background: rgba(255,255,255,0.94);
   137→  backdrop-filter: blur(14px);
   138→  -webkit-backdrop-filter: blur(14px);
   139→  border-bottom: 1px solid var(--color-border);
   140→  z-index: 1000;
   141→  transition: box-shadow var(--transition);
   142→}
   143→.navbar.scrolled { box-shadow: var(--shadow-md); }
   144→
   145→.nav-container {
   146→  max-width: 1080px;
   147→  margin: 0 auto;
   148→  padding: 0 24px;
   149→  height: 100%;
   150→  display: flex;
   151→  align-items: center;
   152→  justify-content: space-between;
