   169→  font-size: 0.7rem;
   170→  font-weight: 400;
   171→  color: var(--color-text-muted);
   172→  letter-spacing: 0.02em;
   173→}
   174→.nav-brand:hover .nav-brand-name { color: var(--color-primary); }
   175→
   176→.nav-links {
   177→  list-style: none;
   178→  display: flex;
   179→  gap: 30px;
   180→}
   181→.nav-links a {
   182→  font-size: 0.875rem;
   183→  font-weight: 500;
   184→  color: var(--color-text-muted);
   185→  text-decoration: none;
   186→  transition: color var(--transition);
   187→  position: relative;
   188→}
   189→.nav-links a::after {
   190→  content: '';
   191→  position: absolute;
   192→  bottom: -4px;
   193→  left: 0;
   194→  width: 0;
   195→  height: 2px;
   196→  background: var(--color-primary);
   197→  border-radius: var(--radius-full);
   198→  transition: width var(--transition);
